// WorkArea is the AIXM WorkArea feature.
type WorkArea struct {
	XMLName xml.Name `xml:"http://www.aixm.aero/schema/5.1.1 WorkArea"`
	FeatureCommon
	TimeSlice []WorkAreaTimeSlice `xml:"http://www.aixm.aero/schema/5.1.1 timeSlice>WorkAreaTimeSlice"`
}

// Kind returns "WorkArea".
func (*WorkArea) Kind() string { return "WorkArea" }

// TimeSlices returns the feature's time slices.
func (f *WorkArea) TimeSlices() []TimeSlice {
	out := make([]TimeSlice, len(f.TimeSlice))
	for i := range f.TimeSlice {
		out[i] = &f.TimeSlice[i]
	}
	return out
}

// WorkAreaTimeSlice holds the properties of WorkArea valid during one time slice.
type WorkAreaTimeSlice struct {
	TimeSliceCommon
	Type                      *CodeWorkArea            `xml:"http://www.aixm.aero/schema/5.1.1 type"`
	PlannedOperational        *Date                    `xml:"http://www.aixm.aero/schema/5.1.1 plannedOperational"`
	AssociatedAirportHeliport *Reference               `xml:"http://www.aixm.aero/schema/5.1.1 associatedAirportHeliport"` // reference to AirportHeliport
	Extent                    *ElevatedSurfaceProperty `xml:"http://www.aixm.aero/schema/5.1.1 extent"`
	Activation                []WorkareaActivity       `xml:"http://www.aixm.aero/schema/5.1.1 activation>WorkareaActivity"`
	Annotation                []Note                   `xml:"http://www.aixm.aero/schema/5.1.1 annotation>Note"`
	Extension                 []Extension              `xml:"http://www.aixm.aero/schema/5.1.1 extension"`
}

